        public static UnitConverterPressureUnit[] GetUnitsForSystem(UnitConverterUnitSystem system)
        {
            var units = new List<UnitConverterPressureUnit>();
            for (int i = 0; i < 66; i++) if (GetUnitSystem((UnitConverterPressureUnit)i) == system) units.Add((UnitConverterPressureUnit)i);
            return units.ToArray();
        }

        public static IReadOnlyList<UnitConverterUnitInfo> GetUnits() { return Metadata.Units; }
        public static UnitConverterUnitInfo GetUnitInfo(UnitConverterPressureUnit unit) { Validate(unit); return Metadata.Units[(int)unit]; }
        public static string GetSymbol(UnitConverterPressureUnit unit, IFormatProvider provider) { return GetUnitInfo(unit).GetSymbol(provider); }

        public static bool TryParseUnit(string text, out UnitConverterPressureUnit unit, IFormatProvider provider = null)
        {
            int id; bool success = UnitConverterText.TryUnit(text, GetUnits(), provider, out id);
            unit = success ? (UnitConverterPressureUnit)id : default(UnitConverterPressureUnit); return success;
        }

        public static UnitConverterPressureUnit ParseUnit(string text, IFormatProvider provider = null)
        {
            UnitConverterPressureUnit unit;
            if (!TryParseUnit(text, out unit, provider)) throw new FormatException("Unknown or ambiguous Pressure unit: " + text);
            return unit;
        }

        public static bool TryParse(string text, out UnitConverterPressureValue quantity, IFormatProvider provider = null)
        {
            double value; int id;
            bool success = UnitConverterText.TryValue(text, GetUnits(), provider, out value, out id);
            quantity = success ? new UnitConverterPressureValue(value, (UnitConverterPressureUnit)id) : default(UnitConverterPressureValue); return success;
        }

        public static UnitConverterPressureValue Parse(string text, IFormatProvider provider = null)
        {
            UnitConverterPressureValue quantity;
            if (!TryParse(text, out quantity, provider)) throw new FormatException("Expected a finite number and an unambiguous Pressure unit.");
            return quantity;
        }

        public static string Format(double value, UnitConverterPressureUnit unit, string format = "G", IFormatProvider provider = null)
        {
            return value.ToString(format, provider ?? CultureInfo.CurrentCulture) + " " + GetSymbol(unit, provider);
        }


